fn bit_wise_xor(arr1: &Vec<i32>, arr2: &Vec<i32>) -> Vec<i32> {
    // Assuming arr1.len() == arr2.len() as per the problem statement
    arr1
        .iter()
        .zip(arr2.iter())
        .map(|(&a, &b)| a ^ b)
        .collect()
}

fn main() {
    let a = vec![1, 2, 3, -1];
    let b = vec![4, 5, 6,  1];
    let result = bit_wise_xor(&a, &b);
    println!("{:?}", result); // [1^4, 2^5, 3^6, (-1)^1] -> [5, 7, 5, -2]
}